type EventLocation = {
  address: string
  label: string
}

export type EventPicture = {
  url: string
  alt: string
  // Tiny base64 preview generated by Sanity, shown while the full image loads
  lqip?: string
  // Dominant colour of the image, extracted by Sanity (e.g. "#fc749c")
  color?: string
}

export type Event = {
  _id: string
  startDate: Date
  endDate: Date
  name: string
  description: string
  location: EventLocation
  pictures: EventPicture[]
  categories: string[]
  ticket: string
}
